import{_ as p,a0 as o,w as l,s as g,ao as n,I as r,x as s,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"使用 GDM 設置來自定義 GNOME 中的登錄屏幕 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GDM 設置來自定義 GNOME 中的登錄屏幕 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GDM 設置來自定義 GNOME 中的登錄屏幕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GDM 設置來自定義 GNOME 中的登錄屏幕 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20240102 Using GDM Settings to Customize Login Screen in GNOME","title":"使用 GDM 設置來自定義 GNOME 中的登錄屏幕","tag":"202401","desc":""},"relativePath":"202401/20240102 Using GDM Settings to Customize Login Screen in GNOME.md","filePath":"[post].md"}'),m={name:"202401/20240102 Using GDM Settings to Customize Login Screen in GNOME.md"};function d(h,t,b,u,c,f){const e=o("Link");return l(),g("div",null,[t[21]||(t[21]=n('<h1 id="使用-gdm-設置來自定義-gnome-中的登錄屏幕" tabindex="-1">使用 GDM 設置來自定義 GNOME 中的登錄屏幕 <a class="header-anchor" href="#使用-gdm-設置來自定義-gnome-中的登錄屏幕" aria-label="Permalink to “使用 GDM 設置來自定義 GNOME 中的登錄屏幕”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/23/111959p1n47oww7wu7f1t4.jpg" alt=""></p><blockquote><p>沒錯，即使是 GNOME 登錄屏幕也可以自定義。這裏有一個方便的實用工具，可以讓事情變得更簡單。</p></blockquote><p>從停靠區到 GRUB 屏幕，GNOME 都可以根據你的喜好進行定製。</p><p>登錄界面也在此列，因為一款名為 “<ruby>GDM 設置<rt>GDM Settings</rt></ruby>”的新工具可讓你更改 GNOME 登錄界面的外觀並調整其功能。</p><p>你可以更改壁紙、主題、圖標、時間格式、頂部面板項目等。你還可以在登錄界面啓用輕擊功能（我喜歡這個）。</p><p>在本教程中，你將瞭解安裝此工具的步驟以及如何使用它來更改 GDM 登錄屏幕的各個方面。</p><p>不用説，你必須使用 GNOME 桌面環境和 GDM 顯示管理器才能按照此處的説明進行操作。</p><blockquote><p>🚧 以這種方式使用設置可能會產生問題。請使用 Timeshift 備份系統設置。如果你容易手忙腳亂，不喜歡排除故障，這篇文章就不適合你。</p></blockquote><h3 id="使用-gdm-設置工具進行調整" tabindex="-1">使用 GDM 設置工具進行調整 <a class="header-anchor" href="#使用-gdm-設置工具進行調整" aria-label="Permalink to “使用 GDM 設置工具進行調整”">​</a></h3><p>讓我們首先看看你可以使用這個很棒的程序進行哪些更改。</p><h4 id="_1、更改-shell-主題、圖標和壁紙" tabindex="-1">1、更改 shell 主題、圖標和壁紙 <a class="header-anchor" href="#_1、更改-shell-主題、圖標和壁紙" aria-label="Permalink to “1、更改 shell 主題、圖標和壁紙”">​</a></h4><p>你可以更改登錄屏幕的主題、圖標和壁紙。這是一個例子。</p><p><img src="https://itsfoss.com/content/images/2024/01/gdm-settings-applied.webp" alt=""></p>',14)),r("p",null,[t[1]||(t[1]=s("要更改主題，你應該先下載它。可以從 ",-1)),i(e,{href:"https://www.gnome-look.org/browse/"},{default:a(()=>[...t[0]||(t[0]=[s("GNOME Look 網站",-1)])]),_:1}),t[2]||(t[2]=s(" 獲取一個。",-1))]),t[22]||(t[22]=n('<p>接下來，確保主題位於 <code>/usr/share/themes</code> 中。存儲在 <code>~/.themes</code> 中的主題對 GDM 設置應用是不可見的。</p><p>在 GDM 設置應用中，轉到 “<ruby>外觀<rt>Appearance</rt></ruby>” 選項卡並選擇 “<ruby>主題<rt>Themes</rt></ruby>”（Shell/圖標/光標）。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-set-log-in-themes-settings.png" alt="GDM 主題設置"></p><p>如果要設置壁紙，請將 “<ruby>背景<rt>Background</rt></ruby>” 更改為 “<ruby>圖像<rt>Image</rt></ruby>”，然後從文件瀏覽器瀏覽圖片。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-set-an-image-settings.png" alt="更換壁紙"></p><p>完成後，單擊 “<ruby>應用<rt>Apply</rt></ruby>”。這將要求輸入密碼。請在出現提示時提供。</p><p>你將收到註銷通知以應用更改。註銷後，更改將可見。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-click-on-logout.png" alt="註銷提示"></p><blockquote><p>💡 你可以更改所有設置然後單擊“應用”，或者每次設置後單擊“應用”。如果按“應用”，則會提示你註銷，每次都需要重新登錄並再次打開該設置應用。</p></blockquote><h4 id="_2、更改字體" tabindex="-1">2、更改字體 <a class="header-anchor" href="#_2、更改字體" aria-label="Permalink to “2、更改字體”">​</a></h4><p>在更改字體之前，你需要為所有用户在系統上安裝該字體。</p><p>為了確保這一點，請將下載的自定義字體文件粘貼到 <code>/usr/local/share/fonts</code>，然後使用以下命令創建字體緩存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fc-cache -f -v</span></span></code></pre></div><p>現在，打開 GDM 設置並轉到“<ruby>字體<rt>Fonts</rt></ruby>”選項卡。在那裏，你可以設置字體、抗鋸齒設置等。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-apply-custom-font-settings.png" alt="更改字體設置"></p><p>你可以看到新字體現已設置為你的登錄屏幕。</p><p><img src="https://itsfoss.com/content/images/2023/12/different-font-applied-1.png" alt="自定義字體"></p><h4 id="_3、更改頂部面板的顏色" tabindex="-1">3、更改頂部面板的顏色 <a class="header-anchor" href="#_3、更改頂部面板的顏色" aria-label="Permalink to “3、更改頂部面板的顏色”">​</a></h4><p>要更改頂部面板顏色，請轉到側欄中的 “<ruby>頂部欄<rt>Top Bar</rt></ruby>” 選項。在 “<ruby>調整<rt>Tweaks</rt></ruby>” 下，啓用 “<ruby>更改背景顏色<rt>Change Background Color</rt></ruby>” 按鈕，然後設置所需的顏色。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-change-topbar-background-color.png" alt="更改頂部面板顏色設置"></p><p>將頂部欄的文本顏色更改為適合你選擇的背景的顏色也同樣重要。</p><p><img src="https://itsfoss.com/content/images/2023/12/panel-color-changed.png" alt="更改頂欄顏色"></p><h4 id="_4、更改時間顯示格式" tabindex="-1">4、更改時間顯示格式 <a class="header-anchor" href="#_4、更改時間顯示格式" aria-label="Permalink to “4、更改時間顯示格式”">​</a></h4><p>使用下拉菜單將時鐘更改為 24 小時或 12 小時格式。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-top-bar-clock-settings.png" alt="更改時間顯示格式設置"></p><p>此外，你可以通過切換相應的按鈕使秒在頂部欄上可見。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-show-seconds-on-top-bar.png" alt="頂欄顯示秒"></p><h4 id="_5、啓用登錄屏幕輕擊" tabindex="-1">5、啓用登錄屏幕輕擊 <a class="header-anchor" href="#_5、啓用登錄屏幕輕擊" aria-label="Permalink to “5、啓用登錄屏幕輕擊”">​</a></h4><p>在大多數發行版中，這是默認行為。即使在系統中啓用了輕擊，GNOME 登錄界面也需要使用鼠標左鍵點擊。</p><p>要更改此設置，請轉到鼠標和觸摸板部分並啓用 “<ruby>輕擊<rt>Tap to Click</rt></ruby>” 按鈕。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-enable-tap-to-click-settings.png" alt="啓用屏幕點擊"></p><p>在同一菜單上，你可以選擇調整鼠標光標大小（如果你覺得它很小）。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-add-different-cursor-size-settings.png" alt="更改鼠標光標大小"></p><h4 id="_6、啓用夜燈" tabindex="-1">6、啓用夜燈 <a class="header-anchor" href="#_6、啓用夜燈" aria-label="Permalink to “6、啓用夜燈”">​</a></h4><p>你可以為 GDM 啓用預定的夜燈。</p><p>轉到 “<ruby>顯示<rt>Display</rt></ruby>”，打開 “<ruby>夜燈<rt>Night Light</rt></ruby>” 按鈕。現在，安排日落到日出或你選擇的方便時間。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-change-night-light-settings.png" alt="啓用夜燈"></p><h4 id="_7、添加徽標和歡迎消息" tabindex="-1">7、添加徽標和歡迎消息 <a class="header-anchor" href="#_7、添加徽標和歡迎消息" aria-label="Permalink to “7、添加徽標和歡迎消息”">​</a></h4><p>轉到 “<ruby>登錄屏幕<rt>Login Screen</rt></ruby>” 選項卡，然後啓用 “<ruby>啓用徽標<rt>Enable Logo</rt></ruby>” 按鈕。這將為你提供一個瀏覽圖像的按鈕。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-enable-logo-settings.png" alt="添加 logo"></p><p>選擇圖像並按 “<ruby>應用<rt>Apply</rt></ruby>”。</p><blockquote><p>📋 在我的系統顯示器上，尺寸高達 128×128 像素的圖像看起來是可以接受的，超出這個尺寸對我來説看起來很大。因此，請相應地選擇尺寸。</p></blockquote><p>應用圖像後，要設置歡迎消息，請啓用歡迎消息按鈕，然後添加你想要顯示的文本。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-enable-welcome-message-settings.png" alt="添加歡迎信息"></p><p>當你選擇用户輸入密碼時，將顯示該消息。</p><p><img src="https://itsfoss.com/content/images/2023/12/logo-and-welcome-message-added.png" alt="登錄屏幕歡迎消息"></p><h4 id="_8、導出和導入設置" tabindex="-1">8、導出和導入設置 <a class="header-anchor" href="#_8、導出和導入設置" aria-label="Permalink to “8、導出和導入設置”">​</a></h4><p>如果你想在其他系統上應用相同的設置，你可以導出設置並將其導入到運行 GDM 設置工具的其他系統上。</p><p>單擊左上角的菜單，然後選擇 “<ruby>導出到文件<rt>Export to file</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-click-on-export-to-file.png" alt="導出到文件"></p><p>將文件命名為 “.ini” 並將其保存在安全的地方。你可以稍後導入。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-save-the-export-file-as-gdm-settings-ini.png" alt="命名文件"></p><h4 id="_9、重置所有設置" tabindex="-1">9、重置所有設置 <a class="header-anchor" href="#_9、重置所有設置" aria-label="Permalink to “9、重置所有設置”">​</a></h4><p>不喜歡你所做的更改？ 有一個簡單的方法可以恢復默認值。</p><p>要重置調整，請單擊左上角的菜單並選擇 “<ruby>重置設置<rt>Reset settings</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/12/gdm-settings-click-on-reset.png" alt="重置設置"></p><p>現在，按 “<ruby>應用<rt>Apply</rt></ruby>”。它會詢問你的密碼。提供後，系統將提示你註銷。</p><p>你可以看到，所有更改均已恢復。</p><h4 id="_10、更多設置" tabindex="-1">10、更多設置 <a class="header-anchor" href="#_10、更多設置" aria-label="Permalink to “10、更多設置”">​</a></h4><p>還有其他可用的調整，例如：</p><ol><li>通過 “<ruby>頂欄<rt>Top Bar</rt></ruby> ⇾ <ruby>電源<rt>Power</rt></ruby> ⇾ <ruby>顯示電池百分比<rt>Show Battery Percentage</rt></ruby>”，在頂欄顯示電池百分比。</li><li>通過 “<ruby>登錄屏幕<rt>Login Screen</rt></ruby> ⇾ <ruby>禁用用户列表<rt>Disable User List</rt></ruby>”，在登錄屏幕上禁用或啓用用户列表。</li><li>通過 “<ruby>電源<rt>Power</rt></ruby>” 選項卡更改屏幕關閉時間、暫停時間和其他電源設置。</li></ol><h3 id="安裝-gdm-設置工具" tabindex="-1">安裝 GDM 設置工具 <a class="header-anchor" href="#安裝-gdm-設置工具" aria-label="Permalink to “安裝 GDM 設置工具”">​</a></h3><p>既然你知道該工具可以進行哪些調整，你可能想自己嘗試一下。讓我們看看如何安裝它。</p><blockquote><p>📋 在 Ubuntu / Pop!_OS 上，GDM 設置工具對我不起作用。我在 Debian 12 Bookworm 上以 Flatpak 應用使用。</p></blockquote><p>GDM 設置工具可以作為 Flatpak 安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub io.github.realmazharhussain.GdmSettings</span></span></code></pre></div>',66)),r("p",null,[t[4]||(t[4]=s("或者，它可以作為 ",-1)),i(e,{href:"https://github.com/gdm-settings/gdm-settings/releases"},{default:a(()=>[...t[3]||(t[3]=[s("AppImage",-1)])]),_:1}),t[5]||(t[5]=s(" 提供。",-1))]),t[23]||(t[23]=n('<p>對於 Arch Linux 用户，請使用 AUR 中的任何 AUR 助手進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yay -S gdm-settings</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>登錄屏幕並不是每個人都可以定製的。除了“輕擊”更改之外，大多數其他更改都只是外觀更改。</p><p>總的來説，對於喜歡自定義設置的每個角落的人們來説，有這樣的選擇是件好事。</p><p>🗨️ 你是那些痴迷於定製的 Linux 用户之一嗎？ 你會嘗試 GDM 設置工具嗎？</p><p><em>（題圖：DA/fb8961d0-852d-4d89-b5b2-d2912b38f6f8）</em></p><hr>',8)),r("p",null,[t[7]||(t[7]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/customize-gdm-login/"},{default:a(()=>[...t[6]||(t[6]=[s("https://itsfoss.com/customize-gdm-login/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sreenath/"},{default:a(()=>[...t[8]||(t[8]=[s("Sreenath",-1)])]),_:1}),t[13]||(t[13]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[9]||(t[9]=[s("lujun9972",-1)])]),_:1}),t[14]||(t[14]=s(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[10]||(t[10]=[s("geekpi",-1)])]),_:1}),t[15]||(t[15]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[11]||(t[11]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[s("LCTT",-1)])]),_:1}),t[19]||(t[19]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[s("Linux中國",-1)])]),_:1}),t[20]||(t[20]=s(" 榮譽推出",-1))])])}const G=p(m,[["render",d]]);export{M as __pageData,G as default};
